Rules.InvariantScript:
ClearCollect(
    colRiskCells,
    ForAll(
        Sequence(25) As i,
        With(
            {
                p: 6 - RoundUp(i.Value / 5, 0),
                s: If(Mod(i.Value, 5) = 0, 5, Mod(i.Value, 5))
            },
            {
                Probability: p,
                Severity: s,
                Score: p * s,
                RiskCount: Coalesce(
                    LookUp(colRiskCounts, Probability = p && Severity = s).RiskCount,
                    0
                )
            }
        )
    )
)
